[
  {
    "name": "Alice.md",
    "rdf": {
      "type": "Person",
      "name": "Alice",
      "givenName": "Alice",
      "@context": {
        "wiki": "https://wiki.example.org/",
        "foaf": "http://xmlns.com/foaf/0.1/"
      },
      "schema:articleBody": "# Alice\n\nAlice is a shape-valid `schema:Person`: she carries the `schema:name` the\nmicro shape requires, so SHACL has nothing to say about this page.\n\n<!-- sparql:start\n```sparql\nPREFIX schema: <https://schema.org/>\n\nSELECT ?name WHERE {\n  ?person a schema:Person ;\n          schema:name ?name .\n}\nORDER BY ?name\n```\n<!-- sparql:end -->"
    }
  },
  {
    "name": "Bob.md",
    "rdf": {
      "type": "Person",
      "givenName": "Bob",
      "@context": {
        "wiki": "https://wiki.example.org/",
        "foaf": "http://xmlns.com/foaf/0.1/"
      },
      "schema:articleBody": "# Bob\n\nBob is a `schema:Person` with no `schema:name`, which the micro shape in\n`ontology.ttl` requires. `wiki check --strict` must report it and exit non-zero."
    }
  },
  {
    "name": "Index.md",
    "rdf": {
      "type": "TechArticle",
      "name": "Index",
      "description": "Entry point for the differential-harness micro corpus.",
      "@context": {
        "wiki": "https://wiki.example.org/",
        "foaf": "http://xmlns.com/foaf/0.1/"
      },
      "schema:articleBody": "# Index\n\nThe micro corpus exercises the differential harness with content that is\ndeliberately wrong: a broken internal link, a wikilink where `link.style` is\n`standard`, a stale inline SPARQL block, a document missing a shape-required\nproperty, and a filename that violates `wiki.filename_pattern`.\n\n- [Alice](Alice.md) \u2014 links to a page that exists.\n- [Missing page](Missing_Page.md) \u2014 links to a page that does not.\n- See also [[Bob]] for the wikilink convention violation.\n\n<!-- sparql:start\n```sparql\nPREFIX schema: <https://schema.org/>\n\nSELECT ?page ?name WHERE {\n  ?page a schema:Person ;\n        schema:name ?name .\n}\nORDER BY ?name\n```\n<!-- sparql:end -->"
    }
  },
  {
    "name": "lowercase-name.md",
    "rdf": {
      "type": "TechArticle",
      "name": "filename violation",
      "@context": {
        "wiki": "https://wiki.example.org/",
        "foaf": "http://xmlns.com/foaf/0.1/"
      },
      "schema:articleBody": "# Filename violation\n\n`lowercase-name.md` does not match `wiki.filename_pattern`\n(`[A-Za-z0-9_()-]+\\.md`), so `wiki lint` must report it."
    }
  }
]

